package com.bhashasetu.service;
import com.bhashasetu.config.BhashaSetuProperties; import com.fasterxml.jackson.databind.*; import java.time.Duration; import java.util.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnExpression; import org.springframework.http.*; import org.springframework.http.client.SimpleClientHttpRequestFactory; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient;
@Service @ConditionalOnExpression("'${GEMINI_API_KEY:}' != ''") public class GeminiProfileExtractionService implements ProfileExtractionService {
 private final BhashaSetuProperties p; private final ObjectMapper json; private final RestClient client; public GeminiProfileExtractionService(BhashaSetuProperties p,ObjectMapper j){this.p=p;this.json=j;SimpleClientHttpRequestFactory f=new SimpleClientHttpRequestFactory();f.setConnectTimeout(Duration.ofSeconds(5));f.setReadTimeout(Duration.ofSeconds(10));this.client=RestClient.builder().requestFactory(f).build();}
 public Map<String,Object> extract(String text,Map<String,Object> current,String question){try{String prompt="Extract only explicit eligibility facts from this Hindi/English user message. Return JSON object with one key attributes. Allowed fields: age, annual_income, family_annual_income, individual_monthly_income, gender, state_or_ut, social_category, occupation, employment_status, student_status, education_level, farmer_status, disability_status, disability_percentage, bpl_status, rural_urban, widow_status, minority_status, marital_status. Do not infer missing facts. Message: "+text; Map<String,Object> body=Map.of("contents",List.of(Map.of("parts",List.of(Map.of("text",prompt)))),"generationConfig",Map.of("responseMimeType","application/json")); JsonNode root=client.post().uri("https://generativelanguage.googleapis.com/v1beta/models/{m}:generateContent?key={k}",p.getGeminiModel(),p.getGeminiApiKey()).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(JsonNode.class); String response=root.path("candidates").path(0).path("content").path("parts").path(0).path("text").asText(); JsonNode attrs=json.readTree(response).path("attributes"); return attrs.isObject()?json.convertValue(attrs,Map.class):Map.of();}catch(Exception e){throw new IllegalStateException("Profile extraction is unavailable. Please try again later.");}}
}
